   0. 全局变量
   ============================================================ */
:root {
  --chat-header-bg: transparent;
  --chat-header-blur: 0px;
  --chat-header-border: transparent;

  --input-area-bg: transparent;
  --input-box-bg: #ffffff;
  --input-box-border: 2px solid #000000;
  --input-box-radius: 999px;
  --input-box-color: #1f2329;
  --input-box-placeholder: transparent;
  --input-box-shadow: none;

  --video-btn-icon: url('https://imgbed.heliar.top/i/kC9glas-HURhTZJh_retouch_2026092915185482.png');
  --info-btn-icon: url('https://imgbed.heliar.top/i/cfvt-_qsF6P04iPc_retouch_2026092915191360.png');
}

/* ============================================================
   1. 聊天页面固定背景图
   ============================================================ */
.chat-detail-screen,
.chat-messages-area {
  background-color: #f5f6f8 !important;
  background-image: url('https://imgbed.heliar.top/i/4O2KKktAlmgqMwhb_IMG_20261009_002904.jpg') !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
}

/* ============================================================
   2. 顶栏（透明 + 整体下移）
   ============================================================ */
.chat-header-custom,
.glass-header {
  position: relative !important;
  min-height: 88px !important;
  height: 88px !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  background: transparent !important;
  backdrop-filter: none !important;
  border-bottom: none !important;
  padding: 56px 10px 8px 10px !important;
  display: flex;
  align-items: center;
}

.header-avatar-container {
  display: none !important;
}

.header-profile-section {
  margin-left: -10px !important;
  margin-right: auto !important;
  transform: translateY(6px) !important; 
}

.chat-header-title {
  color: #ff334b !important;
  font-weight: 600 !important;
  font-size: 16px !important;
  letter-spacing: -0.2px !important;
  position: relative !important;
  overflow: visible !important;
  width: fit-content !important;
  max-width: fit-content !important;
  min-width: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  flex: 0 0 auto !important;
}

.chat-header-title::after {
  content: "" !important;
  position: absolute !important;
  left: 100% !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  margin-left: 2px !important;
  width: 120px !important;
  height: 120px !important;
  background: url('https://imgbed.heliar.top/i/zFSDepEMIWFjvrN9_%E6%97%A0%E6%A0%87%E9%A2%9825_20260920193516.png') no-repeat center / contain !important;
