  display: none !important;
}

.header-btn-phone svg {
  display: none !important;
}

.header-btn-back,
.header-action-btn,
.header-btn-phone,
.header-btn-video,
.header-btn-info {
  transform: translateY(6px) !important;
}

/* ============================================================
   3. 气泡本体（完美拉伸 + 完美换行）
   ============================================================ */
.msg-bubble-wrapper:not(.is-first) {
