}
.nuo-thinking-arrow, .nuo-thinking-icon { 
  display: none !important; 
}

/* 2️⃣ 未展开/已展开 的文案切换 */
.nuo-thinking-label {
  font-size: 0 !important; /* 隐藏系统自带的“思考过程”四个字 */
}

/* 👑 未展开时的文案：忧郁纯文字 */
.nuo-thinking-wrap:not(.is-open) .nuo-thinking-label::after {
  content: "Every moment is like forever";
