}

/* 3️⃣ 展开后的面板：推特卡片级美化 */
.chat-detail-screen {
  --thinking-panel-bg: #ffffff;                    /* 推特纯白底色 */
  --thinking-panel-border-full: 1px solid #ebeef0; /* 推特专属浅灰边框 */
  --thinking-panel-border-left: none;              /* 关掉预设左边丑丑的竖线 */
  --thinking-panel-radius: 16px;                   
  --thinking-panel-shadow: 0 4px 12px rgba(0,0,0,0.04);

  /* 🚨 核心魔法：给顶部的推特头像和网名留出 60px 的专属空间！ */
  --thinking-panel-padding: 60px 16px 16px 16px;   

